import * as THREE from '../three.module.js';
import {createHuman} from './PlayerBody.js';
import {FIELD_POSITIONS} from './FieldingController.js';
export class MatchWorldController {
 constructor(scene,assets,umpire){this.umpire=umpire;this.fielders=FIELD_POSITIONS.map(([name,x,z],i)=>{const p=createHuman(scene,x,z);assets.add(p,{skin:['#8a583d','#bd8860','#66412f'][i%3],kit:'#d9ded5'});return p;});this.nonStriker=createHuman(scene,1.8,-18);assets.add(this.nonStriker,{kit:'#274d68'});this.time=0;}
 update(dt,snapshot,state,ball,result,runupProgress=0){this.time+=dt;this.fielders.forEach((p,i)=>{const f=snapshot?.actors[i],base=FIELD_POSITIONS[i],x=f?.x??base[1],z=f?.z??base[2],speed=Math.hypot(f?.vx||0,f?.vz||0),cycle=Math.sin((f?.distance||0)*6);p.g.position.set(x,i===0?-.16:0,z);p.g.rotation.y=speed>.3?Math.atan2(f.vx,f.vz):Math.atan2(ball.x-x,ball.z-z);p.limbs[0].rotation.x=cycle*.65;p.limbs[1].rotation.x=-cycle*.65;p.limbs[2].rotation.x=-cycle*.5;p.limbs[3].rotation.x=cycle*.5;if(i===0||['catch','collect','pickup'].includes(f?.phase)){p.limbs[2].rotation.x=-.65;p.limbs[3].rotation.x=-.65;if(f?.phase==='catch'){p.limbs[2].rotation.x=-1.6;p.limbs[3].rotation.x=-1.6;}}if(f?.phase==='throw')p.limbs[3].rotation.x=-2.5;});const u=this.umpire;if(u){u.limbs[2].rotation.x=0;u.limbs[3].rotation.x=0;u.limbs[2].rotation.z=0;u.limbs[3].rotation.z=0;u.torso.rotation.y=Math.sin(this.time*.8)*.025;if(state==='result'){if(result==='SIX'){u.limbs[2].rotation.x=-Math.PI;u.limbs[3].rotation.x=-Math.PI;}else if(result==='WIDE'){u.limbs[2].rotation.z=-Math.PI/2;u.limbs[3].rotation.z=Math.PI/2;}else if(['BOWLED','CAUGHT','RUN OUT'].includes(result)){u.limbs[3].rotation.x=-2.4;}else if(result==='FOUR'){u.limbs[3].rotation.x=-1.2;u.limbs[3].rotation.z=Math.sin(this.time*4)*.5;}}}
 const progress=snapshot?.runProgress||0,runs=snapshot?.runs||0;this.nonStriker.g.position.z=progress>0?(runs%2?-1:-18)+(runs%2?-17:17)*progress:-18;this.nonStriker.limbs[0].rotation.x=Math.sin(progress*20)*.6;this.nonStriker.limbs[1].rotation.x=-Math.sin(progress*20)*.6;
 }
}
